import mongoose from 'mongoose';
import { ATTENDANCE_STATUSES, GRADING_PERIODS } from './constants.js';

/**
 * A student's status in one attendance session. Records are generated by the server when the
 * session is created (all PRESENT); class and period are copied from the session so they can
 * never disagree with it and so period summaries need no join.
 */
const attendanceRecordSchema = new mongoose.Schema(
  {
    session: { type: mongoose.Schema.Types.ObjectId, ref: 'AttendanceSession', required: true, immutable: true },
    student: { type: mongoose.Schema.Types.ObjectId, ref: 'Student', required: true, immutable: true },
    class: { type: mongoose.Schema.Types.ObjectId, ref: 'Class', required: true, immutable: true },
    period: { type: String, enum: GRADING_PERIODS, required: true },
    status: { type: String, enum: ATTENDANCE_STATUSES, default: 'PRESENT', required: true },
    updatedBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User', default: null },
  },
  { timestamps: true, collection: 'attendanceRecords', versionKey: false },
);

attendanceRecordSchema.index({ session: 1, student: 1 }, { unique: true });
attendanceRecordSchema.index({ class: 1, period: 1, student: 1 });
attendanceRecordSchema.index({ student: 1 });

export const AttendanceRecord = mongoose.model('AttendanceRecord', attendanceRecordSchema);
